const OwnedPageRefusalDeclarationPath = `$.workflow.steps.*.config.refuse_owned_page ? (@ == true)`
func HandlerDeclaresOwnedPageRefusalSQL(handlerExpr string) string {
  return "COALESCE((SELECT bool_or(jsonb_path_exists(ad.default_config, '" + OwnedPageRefusalDeclarationPath + "')) FROM agent_definitions ad WHERE ad.type = " + handlerExpr + " AND ad.deleted_at IS NULL AND ad.is_active AND COALESCE(ad.is_snapshot, false) = false), false)"
}

func workItemHandlerRefusesOwnedPagesSQL(e string) string { return checks.HandlerDeclaresOwnedPageRefusalSQL(e) }
